import {financeToday} from './finance-utils.js';
export function quizWeek(day=financeToday()){const d=new Date(day+'T12:00:00Z');if(Number.isNaN(d.getTime()))throw Error('Escolha uma data válida.');const offset=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-offset);return d.toISOString().slice(0,10)}
export function quizWeekEnd(week){const d=new Date(week+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+6);return d.toISOString().slice(0,10)}
export function validateQuizQuestions(questions){if(!Array.isArray(questions)||questions.length<1||questions.length>50)throw Error('O quiz precisa ter entre 1 e 50 questões.');const ids=new Set();for(const q of questions){if(!q.id||ids.has(q.id))throw Error('As questões precisam de identificadores únicos.');ids.add(q.id);if(!q.prompt?.trim()||q.prompt.length>2000)throw Error('Preencha o enunciado de cada questão (até 2.000 caracteres).');if(!Array.isArray(q.options)||q.options.length<2||q.options.length>6)throw Error('Cada questão precisa de 2 a 6 alternativas.');const options=new Set();for(const o of q.options){if(!o.id||options.has(o.id)||!o.text?.trim()||o.text.length>1000)throw Error('Preencha todas as alternativas, com identificadores únicos.');options.add(o.id)}if(!options.has(q.correct_option_id))throw Error('Marque a alternativa correta de cada questão.');if((q.explanation||'').length>3000)throw Error('A explicação deve ter até 3.000 caracteres.')}return true}
